import React, { useEffect, useState, useCallback } from "react";

function CommentsSection({ articleId, token }) {
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState("");
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState(null); // { id, isAdmin }

  // ✅ Отримати поточного користувача
  useEffect(() => {
    const fetchUser = async () => {
      if (!token) return;
      try {
        const res = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.ok) {
          const data = await res.json();
          setCurrentUser({
            id: data.id,
            isAdmin: data.is_staff || data.is_superuser,
          });
        }
      } catch (err) {
        console.error("Не вдалося отримати користувача:", err);
      }
    };
    fetchUser();
  }, [token]);

  // ✅ Завантаження коментарів
  const fetchComments = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(
        `http://127.0.0.1:8000/api/comments/?article=${articleId}`
      );
      const data = await res.json();
      setComments(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Помилка при завантаженні коментарів:", err);
    } finally {
      setLoading(false);
    }
  }, [articleId]);

  useEffect(() => {
    fetchComments();
  }, [fetchComments]);

  // ✅ Додавання коментаря
  const handleAddComment = async () => {
    if (!newComment.trim()) return;
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/comments/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: token ? `Bearer ${token}` : "",
        },
        body: JSON.stringify({ article: articleId, content: newComment }),
      });
      if (res.ok) {
        setNewComment("");
        fetchComments();
      } else {
        console.error("Помилка при додаванні коментаря", await res.text());
      }
    } catch (err) {
      console.error("Помилка при додаванні коментаря:", err);
    }
  };

  // ✅ Видалення коментаря
  const handleDeleteComment = async (commentId) => {
    if (!window.confirm("Видалити коментар?")) return;
    try {
      const res = await fetch(
        `http://127.0.0.1:8000/api/comments/${commentId}/`,
        {
          method: "DELETE",
          headers: { Authorization: token ? `Bearer ${token}` : "" },
        }
      );
      if (res.ok) {
        setComments((prev) => prev.filter((c) => c.id !== commentId));
      } else {
        console.error("Помилка при видаленні коментаря", await res.text());
      }
    } catch (err) {
      console.error("Помилка при видаленні коментаря:", err);
    }
  };

  // ✅ Перевірка прав
  const canDelete = (comment) => {
    if (!currentUser) return false;
    return (
      currentUser.isAdmin ||
      Number(comment.user) === Number(currentUser.id)
    );
  };

  return (
    <div className="comments-section">
      <h4>Коментарі</h4>

      {loading ? (
        <p>Завантаження коментарів...</p>
      ) : comments.length > 0 ? (
        comments.map((c) => (
          <div key={c.id} className="comment">
            <div
              className="comment-header"
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <strong>
                {c.user_username || `Користувач #${c.user ?? "?"}`}
              </strong>
              {canDelete(c) && (
                <button
                  className="delete-comment-btn"
                  onClick={() => handleDeleteComment(c.id)}
                  style={{
                    background: "transparent",
                    border: "none",
                    cursor: "pointer",
                    color: "red",
                    fontSize: "18px",
                  }}
                  title="Видалити коментар"
                >
                  🗑️
                </button>
              )}
            </div>
            <p style={{ whiteSpace: "pre-wrap", marginTop: "8px" }}>
              {c.content}
            </p>
          </div>
        ))
      ) : (
        <p>Немає коментарів.</p>
      )}

      {token ? (
        <div className="add-comment" style={{ marginTop: "12px" }}>
          <textarea
            placeholder="Напишіть коментар..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            style={{ width: "100%", minHeight: "60px" }}
          />
          <button onClick={handleAddComment} style={{ marginTop: "8px" }}>
            Надіслати
          </button>
        </div>
      ) : (
        <p>🔒 Увійдіть, щоб залишати коментарі</p>
      )}
    </div>
  );
}

export default CommentsSection;
